old='''    private boolean isConfiguredWorkDay(LocalDate d){int i=d.getDayOfWeek().getValue()-1;return prefs.getBoolean("day_"+i,i<5)&&!getMonthlyRestDays().contains(d.getDayOfMonth());}'''
